begin;
do $$
declare e uuid:=gen_random_uuid(); a uuid:=gen_random_uuid(); co uuid:=gen_random_uuid(); et uuid:=gen_random_uuid(); atok uuid:=gen_random_uuid(); ct uuid:=gen_random_uuid();
 j date:='2026-10-12'; r jsonb; ev jsonb:='[{"action":"debut","heure":"08:00:17"},{"action":"pause","heure":"12:00:00"},{"action":"reprise","heure":"13:00:00"},{"action":"fin","heure":"17:00:38"}]'; p public.pointages; req uuid:=gen_random_uuid(); dem uuid;
begin
 insert into public.employes(id,prenom,nom,pin_hash,role,pointage_actif) values(e,'Essai direct','Technicien','test','employe',true),(a,'Essai direct','Admin','test','admin',false),(co,'Essai direct','Compta','test','compta',false);
 insert into public.sessions(token,employe_id,expire_le) values(et,e,now()+interval '1 hour'),(atok,a,now()+interval '1 hour'),(ct,co,now()+interval '1 hour');
 perform public._pointe_ecrire(e,j,'[{"action":"debut","at":"2026-10-12T21:11:04+02:00"},{"action":"pause","at":"2026-10-12T21:11:56+02:00"}]',e);
 r:=public.admin_pointage_enregistrer(et,j,ev,'',1,req,e);assert not (r->>'ok')::boolean,'technicien interdit';
 r:=public.admin_pointage_enregistrer(ct,j,ev,'',1,req,e);assert not (r->>'ok')::boolean,'compta interdite';
 r:=public.admin_pointage_enregistrer(atok,j,ev,'',1,req,e);assert (r->>'ok')::boolean,r::text;
 select * into p from public.pointages where employe_id=e and jour=j;
 assert p.pointe_etat='termine' and public._pointe_total(p)=480 and p.pointe_version=2,'journée complétée 8h';
 assert not exists(select 1 from public.pointage_corrections where employe_id=e and etat='attente'),'pas de demande en attente';
 r:=public.admin_pointage_enregistrer(atok,j,ev,'',1,req,e);assert (r->>'ok')::boolean,'rejeu idempotent';
 assert (select pointe_version=2 from public.pointages where employe_id=e and jour=j),'rejeu sans réécriture';
 r:=public.admin_decider_heures(atok,e,j,480,'',md5(row_to_json(p)::text));assert (r->>'ok')::boolean,r::text;
 ev:=jsonb_set(ev,'{3,heure}','"16:30:38"');
 r:=public.admin_pointage_enregistrer(atok,j,ev,'Nouvelle vérification',2,gen_random_uuid(),e);assert (r->>'ok')::boolean,r::text;
 select * into p from public.pointages where employe_id=e and jour=j;
 assert public._pointe_total(p)=450 and not p.approuve and p.minutes_refusees=0,'recorrection et invalidation ancienne validation';
 r:=public.admin_decider_heures(atok,e,j,450,'',md5(row_to_json(p)::text));assert (r->>'ok')::boolean,r::text;
 r:=public.pointage_exporter(ct,2026,10,array[e]);assert (r->>'ok')::boolean,r::text;
 assert r->'pointages'->0->'pointe_evenements'->3->>'at' like '%14:30:38%','export heure corrigée UTC';
 r:=public.pointage_corriger(et,j,ev,'Demande du technicien',3,gen_random_uuid(),e);assert (r->>'ok')::boolean,r::text;dem:=(r->>'id')::uuid;
 r:=public.admin_pointage_enregistrer(atok,j,'[{"action":"fin","heure":"09:00"}]','',3,gen_random_uuid(),e);assert not (r->>'ok')::boolean,'ordre invalide rejeté';
 assert (select etat='attente' from public.pointage_corrections where id=dem),'échec conserve demande';
 r:=public.admin_pointage_enregistrer(atok,j,ev,'',2,gen_random_uuid(),e);assert not (r->>'ok')::boolean,'version périmée refusée';
 assert (select etat='attente' from public.pointage_corrections where id=dem),'conflit conserve demande';
 r:=public.admin_pointage_enregistrer(atok,j,ev,'',3,gen_random_uuid(),e);assert (r->>'ok')::boolean,r::text;
 assert (select etat='refusee' from public.pointage_corrections where id=dem),'demande remplacée tracée';
 assert (select count(*)=3 from public.journal where acteur_id=a and action='pointage_correction_acceptee'),'chaque écriture attribuée admin';
 assert (select jsonb_array_length(avant)=2 from public.pointage_corrections where employe_id=e and version=1),'original incomplet conservé';
 select * into p from public.pointages where employe_id=e and jour=j;
 req:=gen_random_uuid();
 r:=public.admin_formulaire_pointage(et,e,j,ev,'Remarque essai',p.pointe_version,req);assert not (r->>'ok')::boolean,'technicien interdit';
 r:=public.admin_formulaire_pointage(atok,e,j,ev,'Remarque essai',p.pointe_version,req);assert (r->>'ok')::boolean,r::text;
 assert (select remarque='Remarque essai' and pointe_evenements is not null from public.pointages where employe_id=e and jour=j),'remarque et événements conservés';
 r:=public.admin_formulaire_pointage(atok,e,j,ev,'Remarque essai',p.pointe_version,req);assert (r->>'ok')::boolean,'rejeu formulaire';
 assert (select pointe_version=p.pointe_version+1 from public.pointages where employe_id=e and jour=j),'pas de double correction';
 r:=public.admin_formulaire_pointage(atok,e,j,ev,'Autre texte',p.pointe_version,req);assert not (r->>'ok')::boolean,'requête altérée refusée';
 r:=public.pointage_exporter(ct,2026,10,array[e]);assert (r->>'ok')::boolean,r::text;
 assert r->'pointages'->0->>'remarque'='Remarque essai','remarque exportée';
 raise notice 'OK : droits, journée incomplète, idempotence, validation, recorrection, export, concurrence, atomicité et journal';
end $$;
rollback;
